Definition VSCR : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!2'D!1,A|:000;!2'a5'a6'a7").

Theorem visit_end_object_deep_ok : forall (LBo : list (Z * Z)) (cr : credit) (sp r V S2 kx : Z) (g : eghost) (c0 c2 : ectx) (r0 : estate),
  g_es g = c0 :: c2 :: r0 ->
  PML.cps_heap L HI PC_VISIT_END_OBJECT r sp VSCR (LBo ++ g_lbv g) cr
    (fun R M => PML.entry L R M sp r VSCR /\ PML.a0 R V /\ True /\ enc_inv M V S2 g /\ ev_guard (g_es g) EvEnd /\ PML.img_ro M /\ PML.lits_ok M /\
                ecredit L cr g kx /\ objs_enc L sp V S2)
    (fun R M R' M' LB' cr' LBk W => exists (g' : eghost) (pay : Z),
        PML.a0 R' 1 /\ enc_inv M' V S2 g' /\ g_es g' = estep (g_es g) EvEnd /\ pay_ok EvEnd pay /\ g_len g' = g_len g + ev_ind (g_es g) EvEnd + pay /\
